/**
 * Encodes {@code value}.
 *
 * @param value a finite value. May not be {@link Double#isNaN() NaNs} or
 *     {@link Double#isInfinite() infinities}.
 * @return this writer.
 */
public JsonWriter value(double value) throws IOException {
  if (this instanceof JsonTreeWriter) {
    writeTreeDouble((JsonTreeWriter) this, value);
    return this;
  }
  if (Double.isNaN(value) || Double.isInfinite(value)) {
    throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
  }
  writeDeferredName();
  beforeValue();
  out.append(Double.toString(value));
  return this;
}

private void writeTreeDouble(JsonTreeWriter treeWriter, double value) throws IOException {
  if (!lenient && (Double.isNaN(value) || Double.isInfinite(value))) {
    throw new IllegalArgumentException("JSON forbids NaN and infinities: " + value);
  }

  LazilyParsedNumber parsedNumber = new LazilyParsedNumber(Double.toString(value));
  JsonReader reader = new JsonReader(new StringReader(parsedNumber.toString()));
  reader.setLenient(true);
  reader.doPeek();
  double canonical = value;
  if (reader.peeked == JsonReader.PEEKED_NUMBER
      && reader.pos + reader.peekedNumberLength <= reader.limit) {
    canonical = Double.parseDouble(
        new String(reader.buffer, reader.pos, reader.peekedNumberLength));
  }
  if (!Double.isNaN(value) && !Double.isInfinite(value) && canonical != value) {
    throw new IllegalStateException("Numeric value changed while writing: " + value);
  }

  JsonPrimitive primitive = new JsonPrimitive(value);
  Number storedNumber = primitive.getAsNumber();
  if (storedNumber.doubleValue() != value && !Double.isNaN(value)) {
    primitive = new JsonPrimitive(storedNumber);
  }

  if (treeWriter.pendingName() != null) {
    JsonObject object = (JsonObject) treeWriter.stack().get(treeWriter.stack().size() - 1);
    object.members().put(treeWriter.pendingName(), primitive);
    treeWriter.pendingName(null);
  } else if (treeWriter.stack().isEmpty()) {
    treeWriter.product(primitive);
  } else {
    JsonElement element = treeWriter.stack().get(treeWriter.stack().size() - 1);
    if (element instanceof JsonArray) {
      ((JsonArray) element).elements().add(primitive);
    } else {
      throw new IllegalStateException();
    }
  }
}

/**
 * Encodes {@code value}.
 *
 * @return this writer.
 */
public JsonWriter value(long value) throws IOException {
  writeDeferredName();
  beforeValue();
  out.write(Long.toString(value));
  return this;
}

/**
 * Encodes {@code value}.
 *
 * @param value a finite value. May not be {@link Double#isNaN() NaNs} or
 *     {@link Double#isInfinite() infinities}.
 * @return this writer.
 */
public JsonWriter value(Number value) throws IOException {
  if (value == null) {
    return nullValue();
  }

  writeDeferredName();
  String string = value.toString();
  if (!lenient
      && (string.equals("-Infinity") || string.equals("Infinity") || string.equals("NaN"))) {
    throw new IllegalArgumentException("Numeric values must be finite, but was " + value);
  }
  beforeValue();
  out.append(string);
  return this;
}

/**
 * Ensures all buffered data is written to the underlying {@link Writer}
 * and flushes that writer.
 */
public void flush() throws IOException {
  if (stackSize == 0) {
    throw new IllegalStateException("JsonWriter is closed.");
  }
  out.flush();

